import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout, theme } from '@atlantis/shared';
import type { NavEntry, NavigationConfig } from '@atlantis/shared';
import styled from '@emotion/styled';
import { Sidebar } from './components/Sidebar';
import { MarkdownViewer } from './components/MarkdownViewer';
import { LangToggle } from './components/LangToggle';

function findEntry(entries: NavEntry[], id: string): NavEntry | undefined {
  for (const entry of entries) {
    if (entry.id === id) return entry;
    if (entry.children) {
      const found = findEntry(entry.children, id);
      if (found) return found;
    }
  }
  return undefined;
}

function flattenLeaves(entries: NavEntry[]): NavEntry[] {
  return entries.flatMap((e) => (e.children ? flattenLeaves(e.children) : e.file ? [e] : []));
}

const WelcomeWrap = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  overflow: hidden;
  position: relative;
  font-family: ${theme.typography.fontFamily};
  background: ${theme.colors.mainBg};
`;

