export interface LangConfig {
  label: string;
  navigation: NavigationConfig;
}

export interface BlogAppProps {
  /** Single-language navigation (use when no language switch is needed) */
  navigation?: NavigationConfig;
  /** Multi-language config — renders a language toggle in the top bar */
  languages?: Record<string, LangConfig>;
  /** Default language key when using `languages` */
  defaultLang?: string;
  /** External locale — when provided, syncs language with the shared locale toggle */
  locale?: string;
  /** Used as the hash segment: #/<hashPrefix>/<entry-id> */
  hashPrefix: string;
  topBarRight?: React.ReactNode;
  /** Welcome screen heading — string or per-language map */
  welcomeTitle?: string | Record<string, string>;
  /** Welcome screen subtitle — string or per-language map */
  welcomeSub?: string | Record<string, string>;
}

function resolveLocalizedText(value: string | Record<string, string>, activeLang: string, fallback: string) {
  if (typeof value === 'string') return value;
  return value[activeLang] ?? value[fallback] ?? Object.values(value)[0] ?? '';
}

export function BlogApp({ navigation, languages, defaultLang, locale: externalLocale, hashPrefix, topBarRight, welcomeTitle = 'Blog', welcomeSub = 'Notes, guides, and references — pick a topic from the sidebar to get started.' }: BlogAppProps) {
  const langKeys = languages ? Object.keys(languages) : [];
  const isMultiLang = langKeys.length > 1;

  const [activeLang, setActiveLang] = useState<string>(() => defaultLang ?? langKeys[0] ?? '');

  // Sync with external locale (from the shell's shared toggle)
  useEffect(() => {
    if (externalLocale && langKeys.includes(externalLocale) && externalLocale !== activeLang) {
      setActiveLang(externalLocale);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [externalLocale]);

  const activeNavigation: NavigationConfig = useMemo(() => {
    if (languages && activeLang) return languages[activeLang].navigation;
    return navigation ?? { entries: [] };
  }, [languages, navigation, activeLang]);

  const leaves = useMemo(() => flattenLeaves(activeNavigation.entries), [activeNavigation]);

  const getEntryFromHash = useCallback(
    (hash: string): NavEntry | undefined => {
      const match = hash.match(new RegExp(`^#\\/${hashPrefix}\\/(.+)$`));
      if (match) return findEntry(activeNavigation.entries, match[1]);
      return undefined;
    },
    [activeNavigation, hashPrefix],
  );

  const [activeEntry, setActiveEntry] = useState<NavEntry | null>(() => {
    return getEntryFromHash(window.location.hash) ?? null;
  });

  // Reset to welcome when language changes
  useEffect(() => {
    setActiveEntry(null);
  }, [activeLang]);

  useEffect(() => {
    const onHashChange = () => {
      const entry = getEntryFromHash(window.location.hash);
      if (entry) setActiveEntry(entry);
    };
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, [getEntryFromHash]);

  const handleSelect = useCallback((entry: NavEntry) => {
    if (!entry.file) return;
    setActiveEntry(entry);
    window.location.hash = `#/${hashPrefix}/${entry.id}`;
  }, [hashPrefix]);

  const currentLeaves = useMemo(() => flattenLeaves(activeNavigation.entries), [activeNavigation]);
  const currentIndex = currentLeaves.findIndex((e) => e.id === activeEntry?.id);
  const prevEntry = currentIndex > 0 ? currentLeaves[currentIndex - 1] : null;
  const nextEntry = currentIndex < currentLeaves.length - 1 ? currentLeaves[currentIndex + 1] : null;

  const pageTitle = activeEntry?.label ?? activeEntry?.name ?? hashPrefix;
  const localizedWelcomeTitle = resolveLocalizedText(welcomeTitle, activeLang, defaultLang ?? langKeys[0] ?? '');
  const localizedWelcomeSub = resolveLocalizedText(welcomeSub, activeLang, defaultLang ?? langKeys[0] ?? '');

  return (
    <Layout
      title={pageTitle}
      activeId={activeEntry?.id ?? null}
      topBarRight={topBarRight}
      sidebar={<Sidebar config={activeNavigation} activeId={activeEntry?.id ?? null} onSelect={handleSelect} hashPrefix={hashPrefix} />}
    >
      {activeEntry?.file ? (
        <MarkdownViewer
          file={activeEntry.file}
          prevEntry={prevEntry}
          nextEntry={nextEntry}
          onNavigate={handleSelect}
        />
      ) : (
        <WelcomeScreen title={localizedWelcomeTitle} sub={localizedWelcomeSub} lang={activeLang} />
      )}
    </Layout>
  );
}

export default BlogApp;
